import whisper
import json
import os

FILLER_WORDS = {
    "um", "uh", "hum", "hmm", "mhm",
    "like", "yeah", "so", "basically", "well", "okay"
}
FILLER_PHRASES = [
    "you know", "i mean", "kind of", "i guess"
]

def transcribe_and_detect(video_path, annotations_path):
    print(f"Transcribing {video_path}...")
    model = whisper.load_model("tiny")
    # Using word_timestamps=True is necessary for the requested task
    result = model.transcribe(video_path, word_timestamps=True, language="en")

    words_info = []
    for segment in result["segments"]:
        if "words" in segment:
            for word_info in segment["words"]:
                # Clean word for matching
                clean_word = word_info["word"].strip().lower().strip(".,?!")
                words_info.append({
                    "word": clean_word,
                    "start": word_info["start"],
                    "end": word_info["end"]
                })

    detected = []

    # Check for single filler words
    for item in words_info:
        if item["word"] in FILLER_WORDS:
            detected.append({
                "word": item["word"],
                "timestamp": round(item["start"], 2),
                "end": item["end"]
            })

    # Check for phrases
    for phrase in FILLER_PHRASES:
        phrase_words = phrase.split()
        phrase_len = len(phrase_words)
        for i in range(len(words_info) - phrase_len + 1):
            if [w["word"] for w in words_info[i:i+phrase_len]] == phrase_words:
                detected.append({
                    "word": phrase,
                    "timestamp": round(words_info[i]["start"], 2),
                    "end": words_info[i+phrase_len-1]["end"]
                })

    detected.sort(key=lambda x: x["timestamp"])

    # Save the full detected info for the next script
    with open("/root/detected_full.json", "w") as f:
        json.dump(detected, f, indent=2)

    # Save the requested annotations format
    annotations = [{"word": d["word"], "timestamp": d["timestamp"]} for d in detected]
    with open(annotations_path, "w") as f:
        json.dump(annotations, f, indent=2)

    print(f"Detected {len(detected)} filler words.")

if __name__ == "__main__":
    transcribe_and_detect("/root/input.mp4", "/root/annotations.json")

